const fs = require("fs");
const XLSX = require("xlsx");
const docx = require("docx");

// Read the inventory data
const wb = XLSX.readFile("testbed/data/product_inventory.xlsx");
const ws = wb.Sheets[wb.SheetNames[0]];
const products = XLSX.utils.sheet_to_json(ws);

// Gather summary stats
const totalProducts = products.length;
const categories = {};
products.forEach(p => {
  const cat = p["Category"].toLowerCase();
  categories[cat] = (categories[cat] || 0) + 1;
});
const prices = products.map(p => p["Price"]);
const minPrice = Math.min(...prices);
const maxPrice = Math.max(...prices);
const avgPrice = (prices.reduce((a, b) => a + b, 0) / prices.length).toFixed(2);
const allInStock = products.every(p => p["In Stock"] === "Yes");

// Build the Word document
const { Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell, WidthType, AlignmentType, BorderStyle, HeadingLevel } = docx;

const borderStyle = { style: BorderStyle.SINGLE, size: 1, color: "999999" };
const cellBorders = { top: borderStyle, bottom: borderStyle, left: borderStyle, right: borderStyle };

function createHeaderCell(text) {
  return new TableCell({
    borders: cellBorders,
    shading: { fill: "2E75B6" },
    children: [new Paragraph({ children: [new TextRun({ text, bold: true, color: "FFFFFF", size: 20, font: "Calibri" })], alignment: AlignmentType.CENTER })],
  });
}

function createCell(text, align = AlignmentType.LEFT) {
  return new TableCell({
    borders: cellBorders,
    children: [new Paragraph({ children: [new TextRun({ text: String(text), size: 20, font: "Calibri" })], alignment: align })],
  });
}

// Table header row
const headerRow = new TableRow({
  children: ["Product ID", "Name", "Category", "Price", "In Stock"].map(h => createHeaderCell(h)),
});

// Data rows
const dataRows = products.map(p =>
  new TableRow({
    children: [
      createCell(p["Product ID"]),
      createCell(p["Name"]),
      createCell(p["Category"]),
      createCell(`$${p["Price"]}`, AlignmentType.RIGHT),
      createCell(p["In Stock"], AlignmentType.CENTER),
    ],
  })
);

// Category breakdown text
const categoryText = Object.entries(categories)
  .sort((a, b) => b[1] - a[1])
  .map(([cat, count]) => `${cat.charAt(0).toUpperCase() + cat.slice(1)} (${count})`)
  .join(", ");

const doc = new Document({
  sections: [
    {
      children: [
        // Title
        new Paragraph({
          heading: HeadingLevel.HEADING_1,
          children: [new TextRun({ text: "Product Inventory Summary", bold: true, size: 32, font: "Calibri" })],
          spacing: { after: 200 },
        }),

        // Date
        new Paragraph({
          children: [new TextRun({ text: `Report Generated: ${new Date().toISOString().split("T")[0]}`, italics: true, size: 20, font: "Calibri", color: "666666" })],
          spacing: { after: 300 },
        }),

        // Overview heading
        new Paragraph({
          heading: HeadingLevel.HEADING_2,
          children: [new TextRun({ text: "Overview", bold: true, size: 26, font: "Calibri" })],
          spacing: { after: 150 },
        }),

        // Summary paragraph
        new Paragraph({
          children: [
            new TextRun({ text: `This inventory contains a total of ${totalProducts} products spanning ${Object.keys(categories).length} categories. `, size: 22, font: "Calibri" }),
            new TextRun({ text: `All ${totalProducts} listed items are marked as In Stock: Yes.`, bold: true, size: 22, font: "Calibri" }),
          ],
          spacing: { after: 150 },
        }),

        // Price summary
        new Paragraph({
          children: [
            new TextRun({ text: `Prices range from $${minPrice} to $${maxPrice}, with an average price of $${avgPrice}. `, size: 22, font: "Calibri" }),
            new TextRun({ text: `Note: One promotional item (AUTUMN10 Cart Discount) is listed at $0.`, size: 22, font: "Calibri" }),
          ],
          spacing: { after: 150 },
        }),

        // Category breakdown
        new Paragraph({
          children: [
            new TextRun({ text: "Category Breakdown: ", bold: true, size: 22, font: "Calibri" }),
            new TextRun({ text: `${categoryText}.`, size: 22, font: "Calibri" }),
          ],
          spacing: { after: 300 },
        }),

        // Product listing heading
        new Paragraph({
          heading: HeadingLevel.HEADING_2,
          children: [new TextRun({ text: "Product Listing", bold: true, size: 26, font: "Calibri" })],
          spacing: { after: 200 },
        }),

        // Table
        new Table({
          width: { size: 100, type: WidthType.PERCENTAGE },
          rows: [headerRow, ...dataRows],
        }),
      ],
    },
  ],
});

// Write the document
Packer.toBuffer(doc).then(buffer => {
  fs.writeFileSync("data/product_inventory_summary.docx", buffer);
  console.log("Document saved to data/product_inventory_summary.docx");
});
